INSERT INTO feature VALUES('net-driver','runtime','Streams between processes over `std.net.Eff`','host-effects','implemented','notable',NULL,'The host interface `std.net.Eff` dials a peer by its key, accepts a dialer, and transmits, receives and disconnects a stream''s frames; `gandr run` serves it over QUIC through iroh, binding the endpoint on the run''s first network operation at the socket `--net-bind` names under the key `GANDR_NET_SECRET` holds, so two processes on one host exchange a ping, and a handler written in the language answers the same `ping` as a second model of `std.net.Eff`. An operation the network refuses is declined, and the run is stuck at it.','core-term runtime-net surface-dispatcher surface-driver','corpus/model/distribution/ping.gandr crates/runtime-net/tests/endpoint.rs crates/runtime-net/tests/net.rs crates/surface-dispatcher/tests/run.rs crates/surface-driver/tests/net.rs','corpus/model/distribution/ping.gandr',NULL);
